command_template:
$certDir = 'C:\My Certificates and CRLs 13'
if (-not (Test-Path $certDir)) {
    Write-Output "Directory not found: $certDir"
    exit 1
}
$deleted = @()
$errors = @()
Get-ChildItem -Path $certDir -Filter '*.cer' | ForEach-Object {
    try {
        $certBytes = [System.IO.File]::ReadAllBytes($_.FullName)
        $cert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2($certBytes)
        if ($cert.NotAfter -lt (Get-Date)) {
            Remove-Item $_.FullName -Force
            $deleted += "$($_.Name) (expired: $($cert.NotAfter.ToString('yyyy-MM-dd')))"
        }
        $cert.Dispose()
    } catch {
        $errors += "$($_.Name): $($_.Exception.Message)"
    }
}
if ($deleted.Count -gt 0) {
    Write-Output "Deleted $($deleted.Count) expired certificate(s):"
    $deleted | ForEach-Object { Write-Output "  - $_" }
} else {
    Write-Output 'No expired certificates found.'
}
if ($errors.Count -gt 0) {
    Write-Output "`nErrors:"
    $errors | ForEach-Object { Write-Output "  - $_" }
}
